// ── Singleton (module-level cache) ──────────────────────────────
class Database {
  constructor(url) {
    if (Database._instance) return Database._instance;
    this.url = url;
    this.connected = false;
    Database._instance = this;
  }
  connect() { this.connected = true; console.log(`Connected to ${this.url}`); }
}
Database._instance = null;

const db1 = new Database('postgres://localhost/mydb');
const db2 = new Database('postgres://other/db');
console.log(db1 === db2); // true — same instance

// ── Factory Function ────────────────────────────────────────────
function createLogger(type) {
  const timestamp = () => new Date().toISOString();
  if (type === 'console') return { log: (m) => console.log(`[${timestamp()}] ${m}`) };
  if (type === 'silent')  return { log: () => {} };
  throw new Error(`Unknown logger type: ${type}`);
}
const logger = createLogger('console');
logger.log('Server started'); // [2026-...] Server started

// ── Builder ─────────────────────────────────────────────────────
class QueryBuilder {
  constructor(table) { this._table = table; this._conditions = []; this._limit = null; }
  where(condition) { this._conditions.push(condition); return this; }
  limit(n)         { this._limit = n; return this; }
  build() {
    let sql = `SELECT * FROM ${this._table}`;
    if (this._conditions.length) sql += ` WHERE ${this._conditions.join(' AND ')}`;
    if (this._limit !== null)    sql += ` LIMIT ${this._limit}`;
    return sql;
  }
}

const query = new QueryBuilder('users')
  .where('active = true')
  .where('age > 18')
  .limit(10)
  .build();
console.log(query);
// SELECT * FROM users WHERE active = true AND age > 18 LIMIT 10

// ── Adapter ─────────────────────────────────────────────────────
class OldPaymentGateway {
  pay(amountCents) { console.log(`Old gateway: ${amountCents} cents`); }
}
class NewPaymentAdapter {
  constructor(oldGateway) { this._gw = oldGateway; }
  charge(amountDollars) { this._gw.pay(Math.round(amountDollars * 100)); }
}
const adapter = new NewPaymentAdapter(new OldPaymentGateway());
adapter.charge(9.99); // Old gateway: 999 cents

// ── Decorator ───────────────────────────────────────────────────
function withLogging(service) {
  return {
    fetch(id) {
      console.log(`[LOG] fetch(${id})`);
      const result = service.fetch(id);
      console.log(`[LOG] result: ${JSON.stringify(result)}`);
      return result;
    }
  };
}
const userService = { fetch: (id) => ({ id, name: 'Alice' }) };
const logged = withLogging(userService);
logged.fetch(42);
// [LOG] fetch(42)
// [LOG] result: {"id":42,"name":"Alice"}

// ── Facade — hide subsystem complexity ─────────────────────────
class VideoEncoder    { encode(file)  { return `encoded:${file}`; } }
class ThumbnailGen    { generate(f)   { return `thumb:${f}`;    } }
class UploadService   { upload(data)  { return `url://${data}`; } }

class VideoUploadFacade {
  constructor() {
    this._encoder   = new VideoEncoder();
    this._thumbGen  = new ThumbnailGen();
    this._uploader  = new UploadService();
  }
  // One simple method drives three subsystems
  process(file) {
    const encoded   = this._encoder.encode(file);
    const thumbnail = this._thumbGen.generate(file);
    const url       = this._uploader.upload(encoded);
    return { url, thumbnail };
  }
}

const facade = new VideoUploadFacade();
console.log(facade.process('talk.mp4'));
// { url: 'url://encoded:talk.mp4', thumbnail: 'thumb:talk.mp4' }

// ── Pattern selection guide ──────────────────────────────────────
// Problem                         → Pattern
// ------------------------------- → ----------
// Need exactly one instance        → Singleton
// Decouple object creation         → Factory Method
// Complex object with many options → Builder
// Incompatible interface           → Adapter
// Add behaviour at runtime         → Decorator
// Simplify complex subsystem       → Facade
